create extension if not exists pgcrypto;
create type person as enum ('nihal','shirin'); create type task_owner as enum ('nihal','shirin','either','both'); create type task_tier as enum ('must','stretch'); create type task_status as enum ('open','done','waiting','blocked'); create type task_category as enum ('outbound','website','content','training','delivery','admin');
create type slip_reason as enum ('unclear_next_step','waiting_on_someone','underestimated','interrupted','energy','reprioritised','forgot','scope_grew','no_longer_valid'); create type invoice_status as enum ('draft','sent','received'); create type tx_direction as enum ('in','out'); create type currency as enum ('INR','AED','USD'); create type metric_key as enum ('calls_booked','connections_sent','posts_published','audits_delivered','proposals_sent');
create table sprints(id uuid primary key default gen_random_uuid(),name text not null,start_date date not null,end_date date not null,goal text not null,target_calls int not null default 0,is_active boolean not null default false,changes_next_sprint text,created_at timestamptz not null default now());
create table tasks(id uuid primary key default gen_random_uuid(),sprint_id uuid references sprints(id),owner task_owner not null,title text not null,notes text,day date not null,tier task_tier not null,category task_category not null,status task_status not null default 'open',waiting_on text,blocked_by uuid references tasks(id),completed_at timestamptz,completed_by person,carried_count int not null default 0,created_at timestamptz not null default now());
create table task_slip_reasons(id uuid primary key default gen_random_uuid(),task_id uuid not null references tasks(id) on delete cascade,reason slip_reason not null,moved_at timestamptz not null default now(),moved_from_day date not null,moved_to_day date not null);
create table daily_hours(id uuid primary key default gen_random_uuid(),person person not null,date date not null,hours numeric(4,1) not null check(hours>=0 and hours<=24),updated_at timestamptz not null default now(),unique(person,date)); create table rest_days(id uuid primary key default gen_random_uuid(),person person not null,date date not null,unique(person,date));
create table metrics(id uuid primary key default gen_random_uuid(),sprint_id uuid references sprints(id),date date not null,key metric_key not null,value numeric not null,logged_by person not null,created_at timestamptz not null default now());
create table transactions(id uuid primary key default gen_random_uuid(),date date not null,direction tx_direction not null,amount numeric not null check(amount>0),currency currency not null default 'INR',category text not null,description text not null,party text,invoice_id uuid,reimbursement_id uuid,created_by person not null,created_at timestamptz not null default now());
create table invoices(id uuid primary key default gen_random_uuid(),party text not null,description text not null,amount numeric not null check(amount>0),currency currency not null default 'INR',issued_date date not null,due_date date not null,status invoice_status not null default 'draft',received_date date,notes text,created_at timestamptz not null default now()); alter table transactions add constraint fk_tx_invoice foreign key(invoice_id) references invoices(id);
create table reimbursements(id uuid primary key default gen_random_uuid(),description text not null,amount numeric not null check(amount>0),currency currency not null default 'INR',requested_by person not null,requested_date date not null,settled boolean not null default false,settled_date date,notes text,created_at timestamptz not null default now()); alter table transactions add constraint fk_tx_reimbursement foreign key(reimbursement_id) references reimbursements(id);
create table calendar_blocks(id uuid primary key default gen_random_uuid(),owner task_owner not null,title text not null,start_at timestamptz not null,end_at timestamptz not null,category task_category not null,notes text,created_at timestamptz not null default now()); create table settings(id int primary key default 1 check(id=1),current_balance numeric,current_balance_as_of date,monthly_burn_override numeric,fx_aed numeric,fx_usd numeric); insert into settings(id) values(1);
do $$ declare t text; begin foreach t in array array['sprints','tasks','task_slip_reasons','daily_hours','rest_days','metrics','transactions','invoices','reimbursements','calendar_blocks','settings'] loop execute format('alter table %I enable row level security',t); execute format('create policy "authenticated full access" on %I for all to authenticated using (true) with check (true)',t); end loop; end $$;
do $$ declare t text; begin if exists (select 1 from pg_publication where pubname = 'supabase_realtime') then foreach t in array array['tasks','transactions','invoices','reimbursements','calendar_blocks','daily_hours','rest_days'] loop if not exists (select 1 from pg_publication_tables where pubname = 'supabase_realtime' and schemaname = 'public' and tablename = t) then execute format('alter publication supabase_realtime add table public.%I', t); end if; end loop; end if; end $$;
